/** Independent synthetic haze/noise fixtures and the actual pipeline/persistence. */
public final class PhotoCleanupTest {
    private static int checks,outside;private static double noisyError,cleanError;
    private static final PhotoCleanup.Analysis FIXED=new PhotoCleanup.Analysis(160,120,2,8192,1024,80,100,44,235,239,245,50,58);
    public static void main(String[] args)throws Exception{strict();estimate();pixels();state();regional();System.out.println("PhotoCleanupTest PASS checks="+checks+" outsidePixels="+outside+" outsideChanges=0 noisySquaredError="+noisyError+" cleanedSquaredError="+cleanError);}
    private static void strict()throws Exception{
        for(int[] v:new int[][]{{-1,0,0},{101,0,0},{0,-1,0},{0,101,0},{0,0,-1},{0,0,101}})expectIllegal(()->new PhotoCleanup(v[0],v[1],v[2],null));
        PhotoCleanup frozen=new PhotoCleanup(0,37,58,FIXED);check(frozen.isNeutral()&&frozen.hasStoredState(),"zero intensity keeps analysis");byte[] b=bytes(frozen);check(PhotoCleanup.read(in(b)).equals(frozen)&&b.length<=40,"small frozen wire");
        for(int i=0;i<b.length;i++){byte[] cut=Arrays.copyOf(b,i);expectIo(()->PhotoCleanup.read(in(cut)));}
        for(int offset:new int[]{0,1,2,3,4}){byte[] bad=b.clone();bad[offset]=(byte)255;expectIo(()->PhotoCleanup.read(in(bad)));}
        expectIllegal(()->new PhotoCleanup.Analysis(0,1,0,0,0,0,0,0,255,255,255,0,0));expectIllegal(()->new PhotoCleanup.Analysis(1,1,0,0,1,0,0,0,255,255,255,0,0));expectIllegal(()->new PhotoCleanup.Analysis(1,1,1,4096,0,0,10,0,255,255,255,1,1));
        expectIllegal(()->new PhotoCleanupEstimator.Patch(new int[64],8,9,null));expectIllegal(()->new PhotoCleanupEstimator.Patch(new int[129*129],129,129,null));
        expectIo(()->PhotoCleanupEstimator.analyze(new int[64],8,8,100,100,List.of(),null,()->true));
        PhotoCleanupEstimator.Patch p=new PhotoCleanupEstimator.Patch(new int[64],8,8,null);expectIllegal(()->PhotoCleanupEstimator.analyze(new int[64],8,8,100,100,Collections.nCopies(13,p),null,null));
    }
    private static void estimate()throws Exception{
        int w=128,h=96;int[] clear=new int[w*h],hazy=new int[w*h],highKey=new int[w*h],mist=new int[w*h];
        for(int y=0;y<h;y++)for(int x=0;x<w;x++){int i=y*w+x;double value=.002+.75*((x/8+y/8)%9)/8.0;clear[i]=argb(value,value*.88,value*.7);hazy[i]=veil(clear[i],.16,.9,.93,.97);highKey[i]=argb(.79+.14*x/(w-1.0),.8+.13*x/(w-1.0),.81+.12*x/(w-1.0));mist[i]=argb(.68+.015*Math.sin(x*.05),.69+.015*Math.sin(x*.05),.7+.015*Math.sin(x*.05));}
        List<PhotoCleanupEstimator.Patch> patches=List.of(patch(64,64,7,12),patch(64,64,11,12),patch(64,64,19,12));
        PhotoCleanup.Analysis a=PhotoCleanupEstimator.analyze(hazy,w,h,4096,3072,patches,null,null);check(a.sourceWidth==4096&&a.sourceHeight==3072&&a.patchCount==3&&a.patchPixels==12288&&a.noiseSamples>64,"original patch metadata retained");check(a.veil>0&&a.hazeConfidence>20&&a.lumaNoise>0&&a.noiseConfidence>0,"haze and real raw-patch noise detected");
        PhotoCleanup onlyHaze=new PhotoCleanup(100,100,0,a);double before=0,after=0;for(int i=0;i<hazy.length;i++){before+=distance(hazy[i],clear[i]);after+=distance(onlyHaze.applyArgb(hazy[i]),clear[i]);}check(after<before*.97,"atmospheric recovery improves known latent haze scene");
        PhotoCleanup.Analysis c=PhotoCleanupEstimator.analyze(clear,w,h,w,h,List.of(),null,null),bright=PhotoCleanupEstimator.analyze(highKey,w,h,w,h,List.of(),null,null),fog=PhotoCleanupEstimator.analyze(mist,w,h,w,h,List.of(),null,null);
        check(c.hazeConfidence<a.hazeConfidence,"clear black reference lowers haze confidence");check(bright.hazeConfidence<=10,"high-key pale background conservative");check(fog.hazeConfidence<=10,"featureless real mist conservative");check(c.noiseConfidence==0&&c.lumaNoise==0&&c.chromaNoise==0,"no original patches does not invent noise estimate");
        int[] flat=new int[64*64];Arrays.fill(flat,0xff999999);PhotoCleanup.Analysis quiet=PhotoCleanupEstimator.analyze(clear,w,h,w,h,List.of(new PhotoCleanupEstimator.Patch(flat,64,64,null)),null,null);check(quiet.lumaNoise==0&&quiet.chromaNoise==0,"clean flat source not blurred");
        byte[] mask=new byte[w*h];PhotoCleanup.Analysis empty=PhotoCleanupEstimator.analyze(hazy,w,h,w,h,patches,mask,null);check(empty.hazeConfidence==0,"empty region cannot infer global haze");
        int[] ownership=flat.clone();PhotoCleanupEstimator.Patch owned=new PhotoCleanupEstimator.Patch(ownership,64,64,null);Arrays.fill(ownership,0);PhotoCleanup.Analysis retained=PhotoCleanupEstimator.analyze(clear,w,h,w,h,List.of(owned),null,null);check(retained.noiseSamples>0&&retained.lumaNoise==0,"patch owns pixels");
    }
    private static void pixels()throws Exception{
        PhotoCleanup active=new PhotoCleanup(100,100,100,FIXED),zero=active.withAmount(0);PhotoAdjustments old=PhotoAdjustments.NONE.with(PhotoAdjustments.Parameter.TEMPERATURE,22).withPalette(new PhotoColorPalette(38,-29,77));PresetPreviewProfile baseline=AdjustedPreviewProfile.of(null,old),neutral=AdjustedPreviewProfile.of(null,old.withCleanup(zero));
        for(int i=0;i<32768;i++){int p=Integer.rotateLeft(i*0x9e3779b9,7)^0x83719821;check(zero.applyArgb(p)==p&&neutral.applyArgb(p)==baseline.applyArgb(p),"zero intensity packed pixel exact");int v=active.applyArgb(p);check((v>>>24)==(p>>>24),"haze alpha exact");if((p>>>24)==0)check(v==p,"hidden RGB preserved");}
        check(active.applyArgb(0xff000000)==0xff000000&&active.applyArgb(0xffffffff)==0xffffffff,"black white endpoints protected");
        Memory noisy=new Memory(160,120);Random random=new Random(73);int[] target=new int[noisy.a.length];for(int y=0;y<noisy.h;y++)for(int x=0;x<noisy.w;x++){int i=y*noisy.w+x,base=x<80?80:180;target[i]=0xff000000|base*0x010101;int n=(int)Math.round(random.nextGaussian()*11);noisy.a[i]=0xff000000|clamp(base+n+(int)Math.round(random.nextGaussian()*3))<<16|clamp(base+n)<<8|clamp(base+n+(int)Math.round(random.nextGaussian()*3));}
        int[] original=noisy.a.clone();PhotoCleanup noiseOnly=active.withHaze(0);PhotoCleanupRenderer.apply(noisy,noiseOnly,null,null);for(int i=0;i<target.length;i++){noisyError+=distance(original[i],target[i]);cleanError+=distance(noisy.a[i],target[i]);}check(cleanError<noisyError*.9,"noise reduction lowers known flat-region error");
        double left=0,right=0;for(int y=2;y<118;y++){left+=(noisy.a[y*160+79]>>>8)&255;right+=(noisy.a[y*160+80]>>>8)&255;}check((right-left)/116>92,"strong edge keeps contrast");
        Memory actual=new Memory(160,120),expected=new Memory(160,120);System.arraycopy(original,0,actual.a,0,original.length);System.arraycopy(original,0,expected.a,0,original.length);PhotoCleanupRenderer.apply(actual,active,null,null);PhotoDetailEffects.denoise(expected,FIXED.lumaNoise,FIXED.chromaNoise,null,null);for(int i=0;i<expected.a.length;i++)expected.a[i]=active.applyArgb(expected.a[i]);check(Arrays.equals(actual.a,expected.a),"noise precedes haze exactly");
        Memory throughProfile=new Memory(160,120);System.arraycopy(original,0,throughProfile.a,0,original.length);AdjustedPreviewProfile.of(null,PhotoAdjustments.NONE.withCleanup(active)).renderPixels(throughProfile,null,null);check(Arrays.equals(throughProfile.a,actual.a),"normal profile includes complete cleanup pipeline");
        PhotoCleanup.Analysis fullSource=new PhotoCleanup.Analysis(6400,4800,FIXED.patchCount,FIXED.patchPixels,FIXED.noiseSamples,FIXED.hazeConfidence,FIXED.noiseConfidence,FIXED.veil,FIXED.airRed,FIXED.airGreen,FIXED.airBlue,FIXED.lumaNoise,FIXED.chromaNoise);Memory scaled=new Memory(160,120),scaledReference=new Memory(160,120);System.arraycopy(original,0,scaled.a,0,original.length);System.arraycopy(original,0,scaledReference.a,0,original.length);PhotoCleanupRenderer.apply(scaled,noiseOnly.withAnalysis(fullSource),null,null);PhotoDetailEffects.denoise(scaledReference,8,9,null,null);check(Arrays.equals(scaled.a,scaledReference.a),"preview noise adapts to original source pixel scale");
        Memory white=new Memory(80,60);Arrays.fill(white.a,0xffffffff);PhotoCleanupRenderer.apply(white,active,null,null);for(int p:white.a)check(p==0xffffffff,"uniform bright background retained");
        Memory stopped=new Memory(160,120);expectIo(()->PhotoCleanupRenderer.apply(stopped,active,()->true,null));
    }
    private static void state()throws Exception{
        PhotoCleanup c=new PhotoCleanup(70,81,53,FIXED);PhotoAdjustments manual=PhotoAdjustments.NONE.with(PhotoAdjustments.Parameter.BRIGHTNESS,11).withPalette(new PhotoColorPalette(25,46,75)).withCleanup(c);
        for(PhotoAdjustments.Parameter p:PhotoAdjustments.Parameter.values())check(manual.with(p,p.min).cleanup.equals(c),"every slider retains independent cleanup");check(manual.withCurves(PhotoCurves.NONE).cleanup.equals(c)&&manual.withHsl(PhotoHsl.NONE).cleanup.equals(c)&&manual.withPalette(PhotoColorPalette.NONE).cleanup.equals(c),"advanced colour tools retain cleanup");check(manual.copyFrom(PhotoAdjustments.NONE,false,true,true).cleanup.equals(c),"colour paste retains cleanup");check(PhotoAdjustments.NONE.copyFrom(manual,true,false,false).cleanup.equals(c),"basic paste includes cleanup");
        Path dir=Files.createTempDirectory("cleanup-state-");try{PhotoEditStore store=new PhotoEditStore(dir.toFile(),"cleanup");PhotoRecipeStore recipes=new PhotoRecipeStore(dir.toFile(),"cleanup");String sha="9".repeat(64);int n=0;
            for(PhotoCleanup value:new PhotoCleanup[]{c,c.withAmount(0),PhotoCleanup.NONE,new PhotoCleanup(100,100,100,null)}){PhotoAdjustments settings=manual.withCleanup(value);PhotoLocalEdits local=local(region(settings));byte[] localWire=localBytes(local);check(ByteBuffer.wrap(localWire).getInt()==(value.hasStoredState()?5:4),"regional wire version");check(PhotoLocalEdits.read(in(localWire)).equals(local),"region analysis roundtrip");PhotoEditStore.Draft draft=new PhotoEditStore.Draft(sha,null,"",0,settings,PhotoGeometry.NONE,PhotoBorder.NONE,local,false);store.save(draft);PhotoEditStore.Draft read=store.read(sha);check(read.adjustments.equals(settings)&&read.localEdits.equals(local)&&read.identity().equals(draft.identity()),"draft retains frozen analysis");check(ByteBuffer.wrap(Files.readAllBytes(find(dir,sha+".draft"))).getInt()==(value.hasStoredState()?0x50454438:0x50454437),"explicit draft version");PhotoRecipeStore.Recipe recipe=recipes.create("清理"+(++n),draft);check(recipes.read(recipe.id).adjustments.equals(settings)&&recipe.apply("a".repeat(64),PhotoGeometry.NONE).adjustments.equals(settings),"recipe reuse fixed effect");check(recipes.rename(recipe.id,"改名"+n).adjustments.equals(settings),"rename preserves analysis");}
            PhotoEditStore.Draft base=new PhotoEditStore.Draft(sha,null,"",0,PhotoAdjustments.NONE,false),positioned=new PhotoEditStore.Draft(sha,null,"",0,PhotoAdjustments.NONE.withCleanup(c.withAmount(0)),false);check(!base.identity().equals(positioned.identity())&&!positioned.hasEffect(),"zero intensity version identity preserved");store.save(positioned);check(store.read(sha).adjustments.cleanup.equals(c.withAmount(0)),"zero intensity analysis survives reopen");
            PhotoEditStore.Draft regionalOnly=new PhotoEditStore.Draft(sha,null,"",0,PhotoAdjustments.NONE,PhotoGeometry.NONE,PhotoBorder.NONE,local(region(PhotoAdjustments.NONE.withCleanup(c.withAmount(0)))),false);check(!regionalOnly.hasEffect()&&!base.identity().equals(regionalOnly.identity()),"pure zero-intensity region retains analysis in version identity");store.save(regionalOnly);check(store.read(sha).identity().equals(regionalOnly.identity()),"pure zero-intensity regional identity roundtrip");store.save(positioned);
            PhotoCleanup zero=c.withAmount(0);PhotoAdjustments zeroGlobal=PhotoAdjustments.NONE.withCleanup(zero);PhotoEditStore.Draft zeroAllA=new PhotoEditStore.Draft(sha,null,"",0,zeroGlobal,PhotoGeometry.NONE,PhotoBorder.NONE,local(region(zeroGlobal)),false),zeroAllB=new PhotoEditStore.Draft(sha,null,"",0,zeroGlobal,PhotoGeometry.NONE,PhotoBorder.NONE,local(region(zeroGlobal.withCleanup(zero.withNoise(zero.noise+1)))),false);check(!zeroAllA.hasEffect()&&!zeroAllB.hasEffect(),"global and regional states both visually zero");Set<String> versions=new HashSet<>();check(versions.add(zeroAllA.identity())&&!versions.add(zeroAllA.identity()),"same zero-effect version deduplicates");store.save(zeroAllA);check(!versions.add(store.read(sha).identity()),"saving zero-effect state does not add version");check(store.replace(sha,zeroAllA,zeroAllB)&&!store.replace(sha,zeroAllA,zeroAllB),"single regional state change applies exactly once");check(versions.add(store.read(sha).identity())&&!versions.add(store.read(sha).identity())&&versions.size()==2,"one change gives one new version after reload");check(store.read(sha).adjustments.cleanup.equals(zero)&&store.read(sha).localEdits.regions().get(0).adjustments.cleanup.equals(zero.withNoise(zero.noise+1)),"all-zero analyses and controls retained");store.save(positioned);
            PhotoEditStore.Draft before=store.read(sha);PhotoAdjustmentCopy.Receipt receipt=PhotoAdjustmentCopy.apply(store,List.of(new PhotoAdjustmentCopy.Target(sha,before,before)),manual,true,false,false,null);check(store.read(sha).adjustments.cleanup.equals(c),"real copy retains frozen analysis");check(receipt.undo(store)==1&&store.read(sha).adjustments.cleanup.equals(before.adjustments.cleanup),"real undo restores analysis");
            store.save(new PhotoEditStore.Draft(sha,null,"",0,manual,false));Path file=find(dir,sha+".draft");byte[] full=Files.readAllBytes(file),body=Arrays.copyOf(full,full.length-32);int at=index(body,bytes(c));check(at>=0,"stored cleanup marker");body[at+1]=(byte)255;Files.write(file,auth(body));expectIo(()->store.read(sha));
            byte[] regional=localBytes(local(region(manual)));int regionAt=index(regional,bytes(c));check(regionAt>=0,"regional cleanup marker");ByteBuffer.wrap(regional).putInt(regionAt+5,0);expectIo(()->PhotoLocalEdits.read(in(regional)));
            PhotoRecipeStore.Recipe broken=recipes.create("损坏测试",new PhotoEditStore.Draft(sha,null,"",0,manual,false));Path recipeFile=find(dir,broken.id+".recipe");byte[] recipeAll=Files.readAllBytes(recipeFile),recipeBody=Arrays.copyOf(recipeAll,recipeAll.length-32);int recipeAt=index(recipeBody,bytes(c));check(recipeAt>=0,"recipe cleanup marker");recipeBody[recipeAt+4]=2;Files.write(recipeFile,auth(recipeBody));expectIo(()->recipes.read(broken.id));
        }finally{remove(dir);}
    }
    private static void regional()throws Exception{
        PhotoCleanup haze=new PhotoCleanup(84,92,0,FIXED);AdjustmentRegion region=region(PhotoAdjustments.NONE.withCleanup(haze));Memory small=new Memory(80,60),large=new Memory(240,180);for(int y=0;y<large.h;y++)for(int x=0;x<large.w;x++)large.a[y*large.w+x]=sample(x/3,y/3);for(int y=0;y<small.h;y++)for(int x=0;x<small.w;x++)small.a[y*small.w+x]=sample(x,y);int[] before=small.a.clone();AdjustmentRegionRenderer.apply(small,List.of(region),1,null,null);AdjustmentRegionRenderer.apply(large,List.of(region),1,null,null);AdjustmentRegion.Brush brush=region.compileBrush(80,60);int inside=0;
        for(int y=0;y<60;y++)for(int x=0;x<80;x++){int i=y*80+x;double w=brush.weight((x+.5)/80,(y+.5)/60)*region.amount;if(w==0){outside++;check(small.a[i]==before[i],"mask exterior packed pixel exact");}else if((before[i]>>>24)!=0){inside++;check(small.a[i]==blend(before[i],haze.applyArgb(before[i]),w),"one composite of restored pixels");}check(small.a[i]==large.a[(3*y+1)*240+3*x+1],"frozen haze consistent across dimensions");}check(inside>0&&outside>0,"region covers inside outside");
        Path dir=Files.createTempDirectory("cleanup-branch-");try{Memory spatial=new Memory(80,60,dir.toFile());System.arraycopy(before,0,spatial.a,0,before.length);AdjustmentRegion noiseRegion=region.withAdjustments(PhotoAdjustments.NONE.withCleanup(haze.withNoise(100)));AdjustmentRegionRenderer.apply(spatial,List.of(noiseRegion),1,null,null);for(int y=0;y<60;y++)for(int x=0;x<80;x++)if(brush.weight((x+.5)/80,(y+.5)/60)==0){outside++;check(spatial.a[y*80+x]==before[y*80+x],"spatial noise branch exterior exact");}try(var files=Files.list(dir)){check(files.findAny().isEmpty(),"private branch scratch removed");}}finally{remove(dir);}
    }
    private static PhotoCleanupEstimator.Patch patch(int w,int h,int seed,int sigma){Random random=new Random(seed);int[] p=new int[w*h];for(int i=0;i<p.length;i++){int n=(int)Math.round(random.nextGaussian()*sigma);p[i]=0xff000000|clamp(140+n+(int)(random.nextGaussian()*3))<<16|clamp(140+n)<<8|clamp(140+n+(int)(random.nextGaussian()*3));}return new PhotoCleanupEstimator.Patch(p,w,h,null);}
    private static int veil(int p,double amount,double ar,double ag,double ab){return argb(PhotoCleanup.linear(((p>>>16)&255)/255.0)*(1-amount)+ar*amount,PhotoCleanup.linear(((p>>>8)&255)/255.0)*(1-amount)+ag*amount,PhotoCleanup.linear((p&255)/255.0)*(1-amount)+ab*amount);}
    private static int argb(double r,double g,double b){return 0xff000000|encoded(r)<<16|encoded(g)<<8|encoded(b);}
    private static int encoded(double v){return clamp((int)Math.round((v<=.0031308?v*12.92:1.055*Math.pow(v,1/2.4)-.055)*255));}
    private static int sample(int x,int y){return ((x+y)%13==0?0:((x*7+y*11)%255+1)<<24)|((x*13+y*3)&255)<<16|((x*7+y*11)&255)<<8|((x*17+y*5)&255);}
    private static double distance(int p,int q){double sum=0;for(int s=0;s<24;s+=8){int d=((p>>>s)&255)-((q>>>s)&255);sum+=d*d;}return sum;}
    private static int blend(int a,int b,double w){int out=a&0xff000000;for(int s=0;s<24;s+=8)out|=(int)Math.round(((a>>>s)&255)+(((b>>>s)&255)-((a>>>s)&255))*w)<<s;return out;}
    private static int clamp(int v){return Math.max(0,Math.min(255,v));}
    private static AdjustmentRegion region(PhotoAdjustments s){return new AdjustmentRegion("cleanup","区域",true,.67,List.of(new PhotoPortrait.Stroke(new double[]{.22,.3,.57,.61},.13,.6,false),new PhotoPortrait.Stroke(new double[]{.4,.45},.035,.3,true)),s,PhotoPortrait.NONE,PhotoPortrait.Settings.NONE,null);}
    private static PhotoLocalEdits local(AdjustmentRegion r){return new PhotoLocalEdits(List.of(),List.of(),PhotoPortrait.NONE,List.of(r));}
    private static byte[] bytes(PhotoCleanup c)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();c.write(new DataOutputStream(b));return b.toByteArray();}
    private static byte[] localBytes(PhotoLocalEdits c)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();c.write(new DataOutputStream(b));return b.toByteArray();}
    private static DataInputStream in(byte[] b){return new DataInputStream(new ByteArrayInputStream(b));}
    private static Path find(Path p,String name)throws IOException{try(var files=Files.walk(p)){return files.filter(f->f.getFileName().toString().equals(name)).findFirst().orElseThrow();}}
    private static byte[] auth(byte[] body)throws Exception{ByteArrayOutputStream b=new ByteArrayOutputStream();b.write(body);b.write(MessageDigest.getInstance("SHA-256").digest(body));return b.toByteArray();}
    private static int index(byte[] a,byte[] b){outer:for(int i=0;i<=a.length-b.length;i++){for(int j=0;j<b.length;j++)if(a[i+j]!=b[j])continue outer;return i;}return -1;}
    private static void remove(Path p)throws IOException{try(var files=Files.walk(p)){for(Path f:files.sorted(Comparator.reverseOrder()).toArray(Path[]::new))Files.delete(f);}}
    private interface Run {void run()throws Exception;}
    private static void expectIo(Run r)throws Exception{try{r.run();throw new AssertionError("accepted invalid wire/cancellation");}catch(IOException expected){checks++;}}
    private static void expectIllegal(Run r)throws Exception{try{r.run();throw new AssertionError("accepted invalid parameters");}catch(IllegalArgumentException expected){checks++;}}
    private static void check(boolean b,String message){if(!b)throw new AssertionError(message);checks++;}
    private static final class Memory implements SpatialPreviewFilter.Pixels {final int w,h;final int[] a;final File scratch;Memory(int w,int h){this(w,h,null);}Memory(int w,int h,File scratch){this.w=w;this.h=h;this.scratch=scratch;a=new int[w*h];}public int width(){return w;}public int height(){return h;}public File scratchDirectory(){return scratch;}public void read(int[] b,int row,int rows){System.arraycopy(a,row*w,b,0,rows*w);}public void write(int[] b,int row,int rows){System.arraycopy(b,0,a,row*w,rows*w);}}
}
